<?php
const TF_WEEK_DAYS=['mon','tue','wed','thu','fri','sat','sun'];
function tfWeek($input){$year=filter_var($input['year']??newYorkNow()->format('o'),FILTER_VALIDATE_INT);$week=filter_var($input['week_no']??newYorkNow()->format('W'),FILTER_VALIDATE_INT);if(!$year||$year<2000||$year>2100||!$week||$week<1||$week>53)throw new InvalidArgumentException('Choose a valid week.');$start=(new DateTimeImmutable('now',new DateTimeZone('America/New_York')))->setISODate($year,$week,1)->setTime(0,0);if((int)$start->format('o')!==$year||(int)$start->format('W')!==$week)throw new InvalidArgumentException('That ISO week does not exist.');$days=[];foreach(TF_WEEK_DAYS as $i=>$key){$date=$start->modify('+'.$i.' days');$days[]=['key'=>$key,'date'=>$date->format('Y-m-d'),'max_hours'=>($date->modify('+1 day')->getTimestamp()-$date->getTimestamp())/3600];}return ['year'=>$year,'week_no'=>$week,'start'=>$start->format('Y-m-d'),'end'=>$start->modify('+6 days')->format('Y-m-d'),'days'=>$days];}
function tfWeekCandidate($input,$user,$permission,$required=true){if(tfAllScope($permission)&&empty($input['candidate_id'])){if($required)throw new InvalidArgumentException('Select a candidate first.');return null;}return tfAttendanceTarget($input,$user,$permission);}
function tfWeekEntries($week,$candidate=null){$where='t.year=? AND t.week_no=? AND t.deleted_at IS NULL';$args=[$week['year'],$week['week_no']];if($candidate){$where.=' AND t.user_id=?';$args[]=$candidate['user_id'];}return tfRows("SELECT t.*,p.name project_name,COALESCE(NULLIF(TRIM(CONCAT_WS(' ',c.firstname,c.lastname)),''),u.nick_name,u.email) user_name,c.id candidate_id FROM teamflow_weekly_timesheets t JOIN users u ON u.id=t.user_id LEFT JOIN teamflow_candidates c ON c.user_id=t.user_id LEFT JOIN teamflow_projects p ON p.id=t.project_id WHERE $where ORDER BY user_name,t.id",$args);}
function tfWeekWork($week,$candidate){if(!$candidate)return [];$end=(new DateTimeImmutable($week['end']))->modify('+1 day')->format('Y-m-d');$rows=tfRows('SELECT a.*,p.name project_name,(SELECT COUNT(*) FROM teamflow_timesheet_worklogs w WHERE w.session_id=a.id) linked_entries FROM teamflow_employee_work_status a LEFT JOIN teamflow_projects p ON p.id=a.project_id WHERE a.user_id=? AND a.deleted_at IS NULL AND a.login_time<? AND (a.logout_time>=? OR (a.logout_time IS NULL AND a.login_time>=?)) ORDER BY a.login_time,a.id',[$candidate['user_id'],$end.' 00:00:00',$week['start'].' 00:00:00',$week['start'].' 00:00:00']);foreach($rows as &$row){$row['daily_hours']=[];$in=tfSessionEpoch($row,'login');$out=$row['logout_time']?tfSessionEpoch($row,'logout'):$in;foreach($week['days'] as $day){$d=new DateTimeImmutable($day['date'].' 00:00:00',new DateTimeZone('America/New_York'));$row['daily_hours'][$day['key']]=round(max(0,min($out,$d->modify('+1 day')->getTimestamp())-max($in,$d->getTimestamp()))/3600,2);}}unset($row);return $rows;}
function tfWeeklyData($input,$user,$permission){$week=tfWeek($input);$candidate=tfWeekCandidate($input,$user,$permission,false);$rows=tfWeekEntries($week,$candidate);if(!empty($input['status']))$rows=array_values(array_filter($rows,fn($r)=>$r['status']===$input['status']));$today=newYorkNow()->format('Y-m-d');$day=null;foreach($week['days'] as $d)if($d['date']===$today)$day=$d['key'];$stats=['today_hours'=>$day?array_sum(array_column($rows,$day.'_hours')):0,'week_hours'=>array_sum(array_column($rows,'total_hours')),'pending'=>count(array_filter($rows,fn($r)=>$r['status']==='Pending')),'approved'=>count(array_filter($rows,fn($r)=>$r['status']==='Approved')),'status'=>count(array_unique(array_column($rows,'status')))===1?$rows[0]['status']:(count($rows)?'Mixed':'Draft')];$caps=[];foreach(['create','edit','delete','export','approve','reject'] as $key)$caps[$key]=!empty($permission['can_'.$key]);return ['week'=>$week,'entries'=>$rows,'daily_work'=>tfWeekWork($week,$candidate),'summary'=>$stats,'scope'=>tfAllScope($permission)?'ALL':'OWN','candidate_id'=>$candidate['id']??null,'permissions'=>$caps];}
function tfCheckDailyTotals($week,$uid){$rows=tfRows('SELECT * FROM teamflow_weekly_timesheets WHERE user_id=? AND year=? AND week_no=? AND deleted_at IS NULL',[$uid,$week['year'],$week['week_no']]);foreach($week['days'] as $day)if(array_sum(array_column($rows,$day['key'].'_hours'))>$day['max_hours']+.001)throw new InvalidArgumentException('Combined hours exceed '.$day['max_hours'].' for '.$day['date'].'.');}
function tfSaveWeekEntry($input,$user,$permission,$existing=null,$deferTotals=false){
 $week=tfWeek($input);$target=tfTarget($input,$user,$permission,$existing);tfQ('SELECT id FROM teamflow_candidates WHERE user_id=? FOR UPDATE',[$target]);$id=$existing['id']??null;if($id){$existing=tfOne('SELECT * FROM teamflow_weekly_timesheets WHERE id=? FOR UPDATE',[$id]);if(!in_array($existing['status'],['Draft','Rejected'],true))throw new DomainException('Submitted and approved entries are locked.');if(isset($input['revision'])&&(int)$input['revision']!==(int)$existing['revision'])throw new InvalidArgumentException('This entry changed since you opened it. Refresh the week and retry.');if((int)$existing['year']!==$week['year']||(int)$existing['week_no']!==$week['week_no'])throw new DomainException('An existing entry cannot be moved to a different week.');}
 $auto=$existing&&$existing['source_type']==='attendance';$type=$auto?$existing['entry_type']:($input['entry_type']??'project');if(!in_array($type,['project','leave','training'],true))throw new InvalidArgumentException('Choose Project, Leave or Training.');$project=$auto?(int)$existing['project_id']:(int)($input['project_id']??0);if($type==='project'&&!$project)throw new InvalidArgumentException('Choose a project.');tfCheckProject($project,$user,$permission);
 $task=$auto?($existing['task_issue_id']??null):(int)($input['task_issue_id']??0);$taskRow=null;if($task){$taskRow=tfOne('SELECT id,summary FROM teamflow_issues WHERE id=? AND project=? AND deleted_at IS NULL',[$task,(string)$project]);if(!$taskRow)throw new InvalidArgumentException('Choose a task belonging to the selected project.');if(!tfAllScope($permission)&&!tfFind('issues',$task,$user,getEffectivePermission('teamflow_issues')))throw new DomainException('Choose one of your assigned tasks.');}
 $data=['user_id'=>$target,'year'=>$week['year'],'week_no'=>$week['week_no'],'entry_type'=>$type,'project_id'=>$project?:null,'task_issue_id'=>$task?:null,'task_name'=>$auto?$existing['task_name']:($taskRow['summary']??tfText($input,'task_name',255,true)),'worked_on'=>$auto?$existing['worked_on']:tfText($input,'worked_on',20000),'status'=>'Draft','revision'=>$id?(int)$existing['revision']+1:0];$total=0;$changed=false;$before=[];$after=[];
 foreach($week['days'] as $day){$field=$day['key'].'_hours';$value=$input[$field]??($existing[$field]??0);if(!is_numeric($value)||(float)$value<0||(float)$value>$day['max_hours'])throw new InvalidArgumentException('Daily hours must be between 0 and '.$day['max_hours'].'.');$data[$field]=round((float)$value,2);$total+=$data[$field];$before[$field]=(float)($existing[$field]??0);$after[$field]=$data[$field];if($id&&abs($before[$field]-$after[$field])>.001)$changed=true;}
 $data['total_hours']=round($total,2);$reason=tfText($input,'adjustment_reason',1000);if($auto&&$changed&&$reason==='')throw new InvalidArgumentException('Add a reason for changing recorded work hours.');
 if($auto){$overrides=json_decode($existing['hours_override_json']??'{}',true)?:[];$recorded=array_fill_keys(TF_WEEK_DAYS,0);foreach(tfRows('SELECT work_date,duration_seconds FROM teamflow_timesheet_worklogs WHERE timesheet_id=?',[$id]) as $log){$day=(int)(new DateTimeImmutable($log['work_date']))->format('N');$recorded[TF_WEEK_DAYS[$day-1]]+=(int)$log['duration_seconds']/3600;}foreach(TF_WEEK_DAYS as $key)if(abs($before[$key.'_hours']-$after[$key.'_hours'])>.001){$delta=round($after[$key.'_hours']-round($recorded[$key],2),2);if(abs($delta)<.001)unset($overrides[$key.'_hours']);else $overrides[$key.'_hours']=['delta'=>$delta];}$data['hours_override_json']=json_encode($overrides);}
 $id=tfWriteRow('teamflow_weekly_timesheets',$data,$id);if($changed)tfWriteRow('teamflow_timesheet_changes',['timesheet_id'=>$id,'actor_id'=>$user['id'],'before_json'=>json_encode($before),'after_json'=>json_encode($after),'reason'=>$reason?:'Manual weekly time correction','created_at'=>date('Y-m-d H:i:s')]);if(!$deferTotals)tfCheckDailyTotals($week,$target);return $id;
}
function tfSaveWeekly($input,$user,$permission){global $conn;$week=tfWeek($input);$candidate=tfWeekCandidate($input,$user,$permission);$rows=$input['entries']??[];if(!is_array($rows)||count($rows)>100)throw new InvalidArgumentException('Save at most 100 entries at once.');$submit=!empty($input['submit']);$conn->begin_transaction();try{tfQ('SELECT id FROM teamflow_candidates WHERE id=? FOR UPDATE',[$candidate['id']]);$ids=[];foreach($rows as $row){$existing=!empty($row['id'])?tfFind('timesheets',(int)$row['id'],$user,$permission):null;if(!empty($row['id'])&&!$existing)throw new DomainException('Timesheet access denied.');if($existing&&(int)$existing['user_id']!==(int)$candidate['user_id'])throw new DomainException('Entry belongs to another candidate.');$action=$existing?'edit':'create';if(empty($permission['can_'.$action]))throw new DomainException('You do not have permission to '.$action.' entries.');$ids[]=tfSaveWeekEntry(array_merge($row,['user_id'=>$candidate['user_id'],'year'=>$week['year'],'week_no'=>$week['week_no']]),$user,$permission,$existing,true);}
  tfCheckDailyTotals($week,$candidate['user_id']);if($submit){if(empty($permission['can_edit']))throw new DomainException('Timesheet submission permission is required.');$entries=array_values(array_filter(tfWeekEntries($week,$candidate),fn($r)=>in_array($r['status'],['Draft','Rejected'],true)));if(!$entries)throw new InvalidArgumentException('There are no draft entries to submit.');tfCheckDailyTotals($week,$candidate['user_id']);if(array_sum(array_column($entries,'total_hours'))<=0)throw new InvalidArgumentException('Enter work hours before submitting your timesheet.');foreach($entries as &$entry){tfQ("UPDATE teamflow_weekly_timesheets SET status='Pending',submitted_at=NOW(),review_note=NULL,revision=revision+1 WHERE id=?",[$entry['id']]);$entry['revision']++;}unset($entry);tfSheetNotice($entries,$user['id'],'Pending');}
  $conn->commit();return $ids;
 }catch(Throwable $e){$conn->rollback();throw $e;}}
function tfReviewWeek($input,$user,$permission){global $conn;if(empty($permission['can_view']))throw new DomainException('Timesheet view permission is required.');$week=tfWeek($input);$candidate=tfWeekCandidate($input,$user,$permission);if((int)$candidate['user_id']===(int)$user['id'])throw new DomainException('You cannot approve your own timesheet.');$status=$input['status']??'';if(!in_array($status,['Approved','Rejected'],true))throw new InvalidArgumentException('Choose Approved or Rejected.');$note=tfText($input,'reason',1000,$status==='Rejected');$ids=$input['entry_ids']??[];if(!is_array($ids)||!$ids||count($ids)>500)throw new InvalidArgumentException('Select the pending entries to review.');$conn->begin_transaction();try{tfQ('SELECT id FROM teamflow_candidates WHERE id=? FOR UPDATE',[$candidate['id']]);$rows=[];foreach(array_unique(array_map('intval',$ids)) as $id){$r=tfFind('timesheets',$id,$user,$permission);if(!$r||(int)$r['user_id']!==(int)$candidate['user_id']||(int)$r['year']!==$week['year']||(int)$r['week_no']!==$week['week_no'])throw new DomainException('Entry is outside this candidate/week.');$r=tfOne('SELECT * FROM teamflow_weekly_timesheets WHERE id=? FOR UPDATE',[$id]);if($r['status']!=='Pending')throw new InvalidArgumentException('An entry has already been reviewed. Refresh and retry.');$r['revision']++;$r['review_note']=$note;tfQ('UPDATE teamflow_weekly_timesheets SET status=?,reviewed_at=NOW(),reviewed_by=?,review_note=?,revision=revision+1 WHERE id=?',[$status,$user['id'],$note,$id]);$rows[]=$r;}tfSheetNotice($rows,$user['id'],$status);$conn->commit();return count($rows);}catch(Throwable $e){$conn->rollback();throw $e;}}
function tfCopyWeek($input,$user,$permission){global $conn;$week=tfWeek($input);$candidate=tfWeekCandidate($input,$user,$permission);$previous=(new DateTimeImmutable($week['start']))->modify('-7 days');$old=tfWeekEntries(tfWeek(['year'=>$previous->format('o'),'week_no'=>$previous->format('W')]),$candidate);$conn->begin_transaction();try{tfQ('SELECT id FROM teamflow_candidates WHERE id=? FOR UPDATE',[$candidate['id']]);$current=tfWeekEntries($week,$candidate);$added=0;foreach($old as $r){if(count($current)>=100)throw new InvalidArgumentException('This week has too many entries to copy.');$duplicate=array_filter($current,fn($c)=>$c['entry_type']===$r['entry_type']&&(int)$c['project_id']===(int)$r['project_id']&&$c['task_name']===$r['task_name']);if($duplicate)continue;if($r['project_id']&&!tfAllScope($permission)&&!in_array((int)$r['project_id'],tfProjectsFor($user['id']),true))continue;$value=array_merge($r,['id'=>null,'user_id'=>$candidate['user_id'],'year'=>$week['year'],'week_no'=>$week['week_no'],'task_issue_id'=>null]);foreach(TF_WEEK_DAYS as $key)$value[$key.'_hours']=0;tfSaveWeekEntry($value,$user,$permission);$current[]=$value;$added++;}$conn->commit();return $added;}catch(Throwable $e){$conn->rollback();throw $e;}}
function tfImportWeekWork($input,$user,$permission){global $conn;$week=tfWeek($input);$candidate=tfWeekCandidate($input,$user,$permission);$conn->begin_transaction();try{tfQ('SELECT id FROM teamflow_candidates WHERE id=? FOR UPDATE',[$candidate['id']]);$count=0;foreach(tfWeekWork($week,$candidate) as $work){if(!$work['logout_time']||$work['linked_entries']||substr($work['login_time'],0,10)<$week['start']||substr($work['logout_time'],0,10)>$week['end'])continue;$existing=tfOne("SELECT id FROM teamflow_weekly_timesheets WHERE user_id=? AND project_id=? AND year=? AND week_no=? AND source_type<>'attendance' AND deleted_at IS NULL LIMIT 1",[$candidate['user_id'],$work['project_id'],$week['year'],$week['week_no']]);if($existing)continue;tfAutomaticTimesheets($work);$count++;}$conn->commit();return $count;}catch(Throwable $e){$conn->rollback();throw $e;}}
function tfArchiveWeekEntry($row,$user){global $conn;$conn->begin_transaction();try{tfQ('SELECT id FROM teamflow_candidates WHERE user_id=? FOR UPDATE',[$row['user_id']]);$fresh=tfOne('SELECT status FROM teamflow_weekly_timesheets WHERE id=? FOR UPDATE',[$row['id']]);if(!$fresh||!in_array($fresh['status'],['Draft','Rejected'],true))throw new DomainException('Only draft or rejected entries can be removed.');tfQ('UPDATE teamflow_weekly_timesheets SET deleted_at=NOW(),revision=revision+1 WHERE id=?',[$row['id']]);$conn->commit();}catch(Throwable $e){$conn->rollback();throw $e;}}
